#include <iostream>
#include <vector>
#include <numeric>

using namespace std;

// Algoritmo rápido de MDC para 32-bit inteiros
int gcd(int a, int b) {
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

struct Element {
    int g;
    int cnt;
};

struct Node {
    long long ans;
    int total_gcd;
    int len;
    int pref_sz;
    int suff_sz;
    Element pref[32];
    Element suff[32];
};

Node tree[400005];
int S[100005];

Node merge(const Node& L, const Node& R) {
    if (L.len == 0) return R;
    if (R.len == 0) return L;

    Node res;
    res.ans = L.ans + R.ans;
    res.len = L.len + R.len;
    res.total_gcd = gcd(L.total_gcd, R.total_gcd);

    // Contar subarrays que cruzam o meio
    for (int i = 0; i < L.suff_sz; ++i) {
        for (int j = 0; j < R.pref_sz; ++j) {
            if (gcd(L.suff[i].g, R.pref[j].g) > 1) {
                res.ans += 1LL * L.suff[i].cnt * R.pref[j].cnt;
            }
        }
    }

    // Construir prefixos
    res.pref_sz = L.pref_sz;
    for (int i = 0; i < L.pref_sz; ++i) {
        res.pref[i] = L.pref[i];
    }
    for (int i = 0; i < R.pref_sz; ++i) {
        int g = gcd(L.total_gcd, R.pref[i].g);
        if (res.pref_sz > 0 && res.pref[res.pref_sz - 1].g == g) {
            res.pref[res.pref_sz - 1].cnt += R.pref[i].cnt;
        } else {
            res.pref[res.pref_sz] = {g, R.pref[i].cnt};
            res.pref_sz++;
        }
    }

    // Construir sufixos
    res.suff_sz = R.suff_sz;
    for (int i = 0; i < R.suff_sz; ++i) {
        res.suff[i] = R.suff[i];
    }
    for (int i = 0; i < L.suff_sz; ++i) {
        int g = gcd(R.total_gcd, L.suff[i].g);
        if (res.suff_sz > 0 && res.suff[res.suff_sz - 1].g == g) {
            res.suff[res.suff_sz - 1].cnt += L.suff[i].cnt;
        } else {
            res.suff[res.suff_sz] = {g, L.suff[i].cnt};
            res.suff_sz++;
        }
    }

    return res;
}

void make_leaf(Node& node, int val) {
    node.len = 1;
    node.total_gcd = val;
    node.ans = (val > 1 ? 1 : 0);
    node.pref_sz = 1;
    node.pref[0] = {val, 1};
    node.suff_sz = 1;
    node.suff[0] = {val, 1};
}

void build(int node, int l, int r) {
    if (l == r) {
        make_leaf(tree[node], S[l]);
        return;
    }
    int mid = l + (r - l) / 2;
    build(2 * node, l, mid);
    build(2 * node + 1, mid + 1, r);
    tree[node] = merge(tree[2 * node], tree[2 * node + 1]);
}

void update(int node, int l, int r, int idx, int val) {
    if (l == r) {
        make_leaf(tree[node], val);
        return;
    }
    int mid = l + (r - l) / 2;
    if (idx <= mid) {
        update(2 * node, l, mid, idx, val);
    } else {
        update(2 * node + 1, mid + 1, r, idx, val);
    }
    tree[node] = merge(tree[2 * node], tree[2 * node + 1]);
}

Node query(int node, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) {
        return tree[node];
    }
    int mid = l + (r - l) / 2;
    if (qr <= mid) {
        return query(2 * node, l, mid, ql, qr);
    }
    if (ql > mid) {
        return query(2 * node + 1, mid + 1, r, ql, qr);
    }
    Node left_res = query(2 * node, l, mid, ql, qr);
    Node right_res = query(2 * node + 1, mid + 1, r, ql, qr);
    return merge(left_res, right_res);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    for (int i = 1; i <= n; ++i) {
        cin >> S[i];
    }

    build(1, 1, n);

    for (int k = 0; k < m; ++k) {
        int type;
        cin >> type;
        if (type == 1) {
            int idx, val;
            cin >> idx >> val;
            update(1, 1, n, idx, val);
        } else {
            int l, r;
            cin >> l >> r;
            Node res = query(1, 1, n, l, r);
            cout << res.ans << "\n";
        }
    }

    return 0;
}
